import { ComponentView } from "./base/ComponentView";
import { ensureElement, createElement } from "../utils/utils";
export class BasketView extends ComponentView {
    constructor(container, events) {
        super(container);
        this.events = events;
        this._list = ensureElement('.basket__list', this.container);
        this._totalPrice = ensureElement('.basket__price', this.container);
        this._button = ensureElement('.basket__button', this.container);
        this._button.addEventListener('click', () => {
            events.emit('order:open');
        });
        this.products = [];
    }
    set products(products) {
        if (products.length) {
            this._list.replaceChildren(...products);
            this.setVisible(this._totalPrice);
            this.setDisabled(this._button, false);
        }
        else {
            this._list.replaceChildren(createElement('p', {
                textContent: 'Корзина пуста'
            }));
            this.setHidden(this._totalPrice);
            this.setDisabled(this._button, true);
        }
    }
    set totalPrice(value) {
        this.setText(this._totalPrice, value);
    }
}
