import { ComponentView } from "./base/ComponentView";
import { ensureElement } from "../utils/utils";
export class PageView extends ComponentView {
    constructor(container, events) {
        super(container);
        this.events = events;
        this._counter = ensureElement('.header__basket-counter', this.container);
        this._catalog = ensureElement('.gallery', this.container);
        this._wrapper = ensureElement('.page__wrapper', this.container);
        this._buttonBasket = ensureElement('.header__basket', this.container);
        this._buttonBasket.addEventListener('click', () => {
            this.events.emit('basket:open');
        });
    }
    set catalog(products) {
        this._catalog.replaceChildren(...products);
    }
    set counter(value) {
        this.setText(this._counter, value);
    }
    set pageLock(value) {
        if (value) {
            this._wrapper.classList.add('page__wrapper_locked');
        }
        else {
            this._wrapper.classList.remove('page__wrapper_locked');
        }
    }
}
