import { Model } from "./base/Model";
export class Product extends Model {
    constructor(data, events) {
        super(data, events);
    }
}
export class Basket extends Model {
    constructor(events) {
        super([], events);
        this.productList = [];
    }
    getBasket() {
        return { basket: this.productList };
    }
    changeBasketCounter() {
        return this.productList.length;
    }
    addProduct(product) {
        const productId = this.productList.findIndex((p) => p.id === product.id);
        if (productId === -1) {
            this.productList.push(product);
        }
        this.events.emit('counter:changed');
    }
    removeProduct(product) {
        const productId = product.id;
        this.productList = this.productList.filter((product) => {
            return product.id !== productId;
        });
        this.events.emit('counter:changed');
    }
    clearBasket() {
        this.productList = [];
    }
    getTotalPrice() {
        return this.productList.reduce((totalPrice, product) => {
            return totalPrice + product.price;
        }, 0);
    }
    getProductIds() {
        return this.productList.map((product) => product.id);
    }
    makeOrder() {
        if (this.productList.length > 0) {
            this.emitChanges('basket:order');
        }
    }
}
export class Catalog extends Model {
    constructor(events) {
        super([], events);
        this.catalog = [];
    }
    setCatalog(products) {
        this.catalog = products.map((product) => (Object.assign(Object.assign({}, product), { inBasket: false })));
        this.emitChanges('catalog:changed', { catalog: this.catalog });
    }
}
export class Order extends Model {
    constructor(events) {
        super({}, events);
        this.order = {
            payment: '',
            address: '',
            email: '',
            phone: '',
        };
        this.total = 0;
        this.items = [];
        this.formErrors = {};
    }
    setOrderField(field, value) {
        if (field === 'payment') {
            this.order[field] = value;
        }
        if (field !== 'payment') {
            this.order[field] = value;
        }
        if (this.validateOrder()) {
            this.events.emit('order:ready', this.order);
        }
    }
    validateOrder() {
        const errors = {};
        if (!this.order.payment) {
            errors.payment = 'Выберите способ оплаты';
        }
        if (!this.order.address) {
            errors.address = 'Укажите адрес доставки';
        }
        if (!this.order.email) {
            errors.email = 'Укажите электронную почту';
        }
        if (!this.order.phone) {
            errors.phone = 'Укажите номер телефона';
        }
        this.formErrors = errors;
        this.events.emit('orderErrors:changed', this.formErrors);
        return Object.keys(errors).length === 0;
    }
    clearOrder() {
        return (this.order = {
            payment: '',
            address: '',
            email: '',
            phone: '',
        });
    }
}
